SELECT /*selectBuyerMpRqQuotaProceStateDetailList*/ Y.NUM , Y.BUYER ,(SELECT COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = Y.BUYER) AS COM_NAME_LOC , Y.QUOTATION_NO , Y.QUOTATION_SEQ , Y.REVISION , SUBSTR(Y.BTOA_DATE,1,4) || '/' || SUBSTR(Y.BTOA_DATE,5,2) || '/' || SUBSTR(Y.BTOA_DATE,7,2) AS BTOA_DATE , Y.DESCRIPTION , Y.UNIT_MEASURE , Y.MAKER_NAME , Y.ATOB_UNIT_PRICE , Y.GR_FLAG , Y.AGENT_NAME , Y.BTOA_USER_ID , Y.BTOA_USER_NAME , Y.SOURCING_STATUS , Y.BUYER_ITEM_NO , SUBSTR(Y.BTOA_END_DATE,1,4) || '/' || SUBSTR(Y.BTOA_END_DATE,5,2) || '/' || SUBSTR(Y.BTOA_END_DATE,7,2) AS BTOA_END_DATE , Y.SPECIFICATION , Y.ITEM_QTY , Y.ORIGIN_NAME , Y.BTOA_NEGO_PRICE , Y.PO_FLAG , Y.KEP_USER_ID , Y.BTOA_USER_DEPT , Y.BID_SUCCESS_FLAG , Y.KEP_USER_NAME , Y.BTOA_END_TIME , Y.REG_ITEM_NO , Y.CONTRACT_NO , Y.CONTRACT_SEQ , Y.BYCA_COMORG_CODE , Y.AGENT_OPEN_FLAG , Y.BTOA_REMARK , Y.ATOB_REMARK , Y.BUYER_NAME , Y.BUYER_CATEG_PATH , (SELECT PRODUCT_CLOSE_FLAG FROM ICOMBYIT WHERE BUYER=(SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=Y.BUYER AND STATUS <> 'D') AND BUYER_ITEM_NO=Y.BUYER_ITEM_NO AND STATUS <> 'D') AS PRODUCT_CLOSE_FLAG , Y.IMAGE_KEY , Y.RECV_FLAG , Y.LEAD_TIME , Y.DELAY_REASON_CODE , Y.CONFIRM_USER_ID , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID =Y.CONFIRM_USER_ID) AS CONFIRM_USER_NM , Y.PRE_GR_FLAG , Y.BUYER_MSDS_YN , Y.SAFETY_FLAG , Y.SAFETY_FLAG_TEXT , Y.CANCEL_REMARK FROM( SELECT ROWNUM AS NUM , X.BUYER , X.QUOTATION_NO , X.QUOTATION_SEQ , X.REVISION , X.BTOA_DATE , X.DESCRIPTION , X.UNIT_MEASURE , X.MAKER_NAME , X.ATOB_UNIT_PRICE , X.GR_FLAG , X.AGENT_NAME , X.BTOA_USER_ID , X.BTOA_USER_NAME , X.SOURCING_STATUS , X.BUYER_ITEM_NO , X.BTOA_END_DATE , X.SPECIFICATION , X.ITEM_QTY , X.ORIGIN_NAME , X.BTOA_NEGO_PRICE , X.PO_FLAG , X.KEP_USER_ID , X.BTOA_USER_DEPT , X.BID_SUCCESS_FLAG , X.KEP_USER_NAME , X.BTOA_END_TIME , X.REG_ITEM_NO , X.CONTRACT_NO , X.CONTRACT_SEQ , X.BYCA_COMORG_CODE , X.AGENT_OPEN_FLAG , X.BTOA_REMARK , X.ATOB_REMARK , X.BUYER_NAME , X.BUYER_CATEG_PATH , X.IMAGE_KEY , X.RECV_FLAG , X.LEAD_TIME , X.DELAY_REASON_CODE , X.CONFIRM_USER_ID , X.PRE_GR_FLAG , X.BUYER_MSDS_YN , X.SAFETY_FLAG , (SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'M160' AND COD.CODE = X.SAFETY_FLAG) SAFETY_FLAG_TEXT , X.CANCEL_REMARK FROM( SELECT A.BUYER , A.QUOTATION_NO , A.QUOTATION_SEQ , A.REVISION , A.BTOA_DATE AS BTOA_DATE , A.DESCRIPTION AS DESCRIPTION , A.UNIT_MEASURE AS UNIT_MEASURE , A.MAKER_NAME AS MAKER_NAME , NVL(B.ATOB_UNIT_PRICE,0) AS ATOB_UNIT_PRICE , '' AS GR_FLAG , TRIM(A.ATOB_REMARK) AS ATOB_REMARK , DECODE((SELECT COUNT(*) FROM KEPQTDT QT WHERE QT.BUYER=A.BUYER AND QT.QUOTATION_NO=A.QUOTATION_NO AND QT.QUOTATION_SEQ=A.QUOTATION_SEQ AND QT.REVISION=A.REVISION AND QT.STATUS ='C'),0,'', DECODE(NVL(A.AGENT_OPEN_FLAG,'N'),'N', (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = 'KRKORE0001'), (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = B.AGENT))) AS AGENT_NAME , A.BTOA_USER_ID AS BTOA_USER_ID , A.BTOA_USER_NAME AS BTOA_USER_NAME , CASE WHEN A.RECV_FLAG='GD' THEN '견적취소' ELSE CASE WHEN A.RECV_FLAG='CM' AND (SELECT MAX(PRODUCT_CLOSE_FLAG) FROM ICOMBYIT WHERE BUYER=(SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=A.BUYER AND STATUS <> 'D') AND BUYER_ITEM_NO=A.REG_ITEM_NO AND STATUS <> 'D') = 'G' THEN '코드부여중' ELSE CASE WHEN A.RECV_FLAG='NG' THEN '의뢰결재중' ELSE CASE WHEN A.RECV_FLAG='NR' THEN '의뢰반려' ELSE CASE WHEN A.RECV_FLAG='CC' THEN '장바구니' ELSE CASE WHEN A.RECV_FLAG='PC' THEN '발주' ELSE CASE WHEN A.RECV_FLAG='CM' THEN '합의완료' ELSE CASE WHEN A.RECV_FLAG='PM' THEN '견적진행중' ELSE CASE WHEN A.RECV_FLAG = 'GS' THEN '결재진행중' ELSE CASE WHEN A.RECV_FLAG = 'GR' THEN '결재반려' ELSE CASE WHEN A.RECV_FLAG = 'NW' THEN '견적의뢰' ELSE CASE WHEN A.RECV_FLAG = 'CR' THEN '견적의뢰' ELSE CASE WHEN A.RECV_FLAG = 'RJ' THEN '견적의뢰' ELSE CASE WHEN A.KEP_USER_ID IS NULL THEN '견적의뢰' ELSE CASE WHEN A.BTOA_NEGO_PRICE<>0 AND A.ATOB_UNIT_PRICE=0 AND A.ATOB_SEND_FLAG='Y' THEN 'Nego견적의뢰' ELSE CASE WHEN A.ATOB_UNIT_PRICE=0 AND A.BTOA_NEGO_PRICE=0 AND A.ATOB_SEND_FLAG='N' THEN '견적진행중' ELSE CASE WHEN A.ATOB_UNIT_PRICE =0 AND A.BTOA_NEGO_PRICE<>0 AND A.ATOB_SEND_FLAG='N' THEN 'Nego진행중' ELSE CASE WHEN A.ATOB_UNIT_PRICE <>0 AND A.BTOA_NEGO_PRICE=0 AND A.ATOB_SEND_FLAG='Y' AND B.BID_SUCCESS_FLAG='Y' THEN '단가합의대상' ELSE CASE WHEN A.BTOA_NEGO_PRICE <>0 AND A.ATOB_UNIT_PRICE <>0 AND A.ATOB_SEND_FLAG='Y' AND B.BID_SUCCESS_FLAG='Y' THEN 'Nego합의대상' END END END END END END END END END END END END END END END END END END END AS SOURCING_STATUS , A.RECV_FLAG AS RECV_FLAG , A.BUYER_ITEM_NO AS BUYER_ITEM_NO , A.BTOA_END_DATE AS BTOA_END_DATE , SUBSTR(NVL(A.BTOA_END_TIME,'00'),0,2)||':'||SUBSTR(NVL(A.BTOA_END_TIME,'00'),3,2) AS BTOA_END_TIME , A.SPECIFICATION AS SPECIFICATION , NVL(A.ITEM_QTY,0) AS ITEM_QTY , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE='M001' AND CODE=A.ORIGIN_CODE) AS ORIGIN_NAME , NVL(A.BTOA_NEGO_PRICE,0) AS BTOA_NEGO_PRICE , '' AS PO_FLAG , A.KEP_USER_ID AS KEP_USER_ID , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE=A.BUYER AND TYPE='C001' AND CODE=A.BTOA_USER_DEPT) AS BTOA_USER_DEPT , NVL(B.BID_SUCCESS_FLAG,'N') AS BID_SUCCESS_FLAG , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID=A.KEP_USER_ID) AS KEP_USER_NAME , A.REG_ITEM_NO AS REG_ITEM_NO , A.CONTRACT_NO AS CONTRACT_NO , A.CONTRACT_SEQ AS CONTRACT_SEQ , (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=A.BUYER AND STATUS IN ('C','R')) AS BYCA_COMORG_CODE , A.AGENT_OPEN_FLAG AS AGENT_OPEN_FLAG , A.BTOA_REMARK AS BTOA_REMARK , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER) AS BUYER_NAME , (SELECT H.CATEG_PATH FROM ICOMBYCA H WHERE H.COM_CODE = A.BUYER AND H.STD_CATEG_ID IN (SELECT CATEGORY_NO FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO)) AS BUYER_CATEG_PATH , DECODE(NVL((SELECT INCOME_PRICE_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = A.BUYER),'N'),'N',0, B.STOA_LIST_PRICE) AS STOA_LIST_PRICE , A.IMAGE_KEY AS IMAGE_KEY , B.LEAD_TIME AS LEAD_TIME , A.DELAY_REASON_CODE AS DELAY_REASON_CODE , A.CONFIRM_USER_ID AS CONFIRM_USER_ID , A.PRE_GR_FLAG AS PRE_GR_FLAG , NVL(A.BUYER_MSDS_YN,'N') AS BUYER_MSDS_YN , A.SAFETY_FLAG AS SAFETY_FLAG , A.CANCEL_REMARK AS CANCEL_REMARK FROM KEPRQDT A, KEPQTDT B WHERE 1=1
AND A.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'BGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.TEXT1 = #{st_group_info} AND COD3.FLAG = 'Y')
AND A.BUYER = #{st_buyer}
AND A.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y')
AND A.BUYER = #{st_buyer}
AND A.SO_CA_FLAG='SO' AND A.RECV_FLAG ^='TS' AND A.BUYER=B.BUYER(+) AND A.QUOTATION_NO=B.QUOTATION_NO(+) AND A.QUOTATION_SEQ=B.QUOTATION_SEQ(+) AND A.REVISION=B.REVISION(+) AND A.STATUS IN ('C','R') AND B.STATUS (+)= 'C' AND B.STOA_LIST_PRICE (+) > 0 AND 'D' <> B.STATUS(+)
AND A.BTOA_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BTOA_USER_ID = #{st_user_id}
AND A.QUOTATION_NO LIKE '%'||#{st_quotation_no}||'%'
AND A.BTOA_USER_DEPT = #{st_btoa_user_dept_code}
AND A.BUYER_ITEM_NO = #{st_search_code}
AND UPPER(A.DESCRIPTION) LIKE UPPER('%'||#{st_search_code}||'%')
AND UPPER(A.SPECIFICATION) LIKE UPPER('%'||#{st_search_code}||'%')
AND A.BTOA_USER_NAME LIKE '%'||#{st_btoa_user_name}||'%'
AND CASE WHEN A.RECV_FLAG='GD' THEN '견적취소' ELSE CASE WHEN A.RECV_FLAG='CM' AND (SELECT MAX(PRODUCT_CLOSE_FLAG) FROM ICOMBYIT WHERE BUYER=(SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=A.BUYER AND STATUS <> 'D') AND BUYER_ITEM_NO=A.REG_ITEM_NO AND STATUS <> 'D') = 'G' THEN '코드부여중' ELSE CASE WHEN A.RECV_FLAG='CC' THEN '합의완료+장바구니' ELSE CASE WHEN A.RECV_FLAG='PC' THEN '발주' ELSE CASE WHEN A.RECV_FLAG='CM' THEN '합의완료' ELSE CASE WHEN A.RECV_FLAG='PM' THEN '견적진행중' ELSE CASE WHEN A.RECV_FLAG = 'GS' THEN '결재진행중' ELSE CASE WHEN A.RECV_FLAG = 'NG' THEN '의뢰결재중' ELSE CASE WHEN A.RECV_FLAG = 'NR' THEN '의뢰반려' ELSE CASE WHEN A.RECV_FLAG = 'GR' THEN '결재반려' ELSE CASE WHEN A.RECV_FLAG = 'NW' THEN '견적의뢰' ELSE CASE WHEN A.RECV_FLAG = 'CR' THEN '견적의뢰' ELSE CASE WHEN A.RECV_FLAG = 'RJ' THEN '견적의뢰' ELSE CASE WHEN A.KEP_USER_ID IS NULL THEN '견적의뢰' ELSE CASE WHEN A.BTOA_NEGO_PRICE<>0 AND A.ATOB_UNIT_PRICE=0 AND A.ATOB_SEND_FLAG='Y' THEN 'Nego견적의뢰' ELSE CASE WHEN A.ATOB_UNIT_PRICE=0 AND A.BTOA_NEGO_PRICE=0 AND A.ATOB_SEND_FLAG='N' THEN '견적진행중' ELSE CASE WHEN A.ATOB_UNIT_PRICE=0 AND A.BTOA_NEGO_PRICE<>0 AND A.ATOB_SEND_FLAG='N' THEN 'Nego진행중' ELSE CASE WHEN A.ATOB_UNIT_PRICE<>0 AND A.BTOA_NEGO_PRICE=0 AND A.ATOB_SEND_FLAG='Y' AND B.BID_SUCCESS_FLAG='Y' THEN '단가합의대상' ELSE CASE WHEN A.BTOA_NEGO_PRICE<>0 AND A.ATOB_UNIT_PRICE<>0 AND A.ATOB_SEND_FLAG='Y' AND B.BID_SUCCESS_FLAG='Y' THEN 'Nego합의대상' END END END END END END END END END END END END END END END END END END END LIKE '%'||#{st_sourcing_status}||'%'
AND A.BTOA_USER_ID = #{st_user_id}
AND A.RECV_FLAG ^='GD'
AND A.BTOA_USER_ID IN (SELECT COD3.CODE1 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'M-01' AND COD3.BUYER = #{st_buyer} AND COD3.CODE2 = #{st_user_id} AND COD3.TEXT4 = 'A' AND COD3.FLAG = 'Y')
)X ORDER BY X.BUYER, X.QUOTATION_NO, X.QUOTATION_SEQ, X.REVISION ) Y

SELECT /* selectBuyerMpRqQuotaProceStateNegoList */ Y.NUM , Y.BUYER ,(SELECT COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = Y.BUYER) AS COM_NAME_LOC , Y.QUOTATION_NO , Y.QUOTATION_SEQ , Y.REVISION , SUBSTR(Y.BTOA_DATE,1,4) || '/' || SUBSTR(Y.BTOA_DATE,5,2) || '/' || SUBSTR(Y.BTOA_DATE,7,2) AS BTOA_DATE , Y.DESCRIPTION , Y.UNIT_MEASURE , Y.MAKER_NAME , Y.ATOB_UNIT_PRICE , Y.GR_FLAG , Y.AGENT_NAME , Y.BTOA_USER_ID , Y.BTOA_USER_NAME , Y.SOURCING_STATUS , Y.BUYER_ITEM_NO , SUBSTR(Y.BTOA_END_DATE,1,4) || '/' || SUBSTR(Y.BTOA_END_DATE,5,2) || '/' || SUBSTR(Y.BTOA_END_DATE,7,2) AS BTOA_END_DATE , Y.SPECIFICATION , Y.ITEM_QTY , Y.ORIGIN_NAME , Y.BTOA_NEGO_PRICE , Y.PO_FLAG , Y.KEP_USER_ID , Y.BTOA_USER_DEPT , Y.BID_SUCCESS_FLAG , Y.KEP_USER_NAME , Y.AGENT , Y.BTOA_END_TIME , Y.REG_ITEM_NO , Y.CONTRACT_NO , Y.CONTRACT_SEQ , Y.BYCA_COMORG_CODE , Y.AGENT_OPEN_FLAG , Y.BTOA_REMARK , Y.ATOB_REMARK , Y.BUYER_NAME , Y.BUYER_CATEG_PATH , (SELECT PRODUCT_CLOSE_FLAG FROM ICOMBYIT WHERE BUYER=(SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=Y.BUYER AND STATUS <> 'D') AND BUYER_ITEM_NO=Y.BUYER_ITEM_NO AND STATUS <> 'D') AS PRODUCT_CLOSE_FLAG , Y.IMAGE_KEY , Y.RECV_FLAG , Y.BID_SUCCESS_QUOTATION_SEQ , Y.LEAD_TIME , Z.NEGO_SEQ , Z.BTOA_NEGO_PRICE AS NEGO_BTOA_NEGO_PRICE , Z.ATOB_UNIT_PRICE AS NEGO_ATOB_UNIT_PRICE FROM( SELECT ROWNUM AS NUM , X.BUYER , X.QUOTATION_NO , X.QUOTATION_SEQ , X.REVISION , X.BTOA_DATE , X.DESCRIPTION , X.UNIT_MEASURE , X.MAKER_NAME , X.ATOB_UNIT_PRICE , X.GR_FLAG , X.AGENT_NAME , X.BTOA_USER_ID , X.BTOA_USER_NAME , X.SOURCING_STATUS , X.BUYER_ITEM_NO , X.BTOA_END_DATE , X.SPECIFICATION , X.ITEM_QTY , X.ORIGIN_NAME , X.BTOA_NEGO_PRICE , X.PO_FLAG , X.KEP_USER_ID , X.BTOA_USER_DEPT , X.BID_SUCCESS_FLAG , X.KEP_USER_NAME , X.AGENT , X.BTOA_END_TIME , X.REG_ITEM_NO , X.CONTRACT_NO , X.CONTRACT_SEQ , X.BYCA_COMORG_CODE , X.AGENT_OPEN_FLAG , X.BTOA_REMARK , X.ATOB_REMARK , X.BUYER_NAME , X.BUYER_CATEG_PATH , X.IMAGE_KEY , X.RECV_FLAG , X.BID_SUCCESS_QUOTATION_SEQ , X.LEAD_TIME FROM( SELECT A.BUYER , A.QUOTATION_NO , A.QUOTATION_SEQ , A.REVISION , MAX(A.BTOA_DATE) AS BTOA_DATE , MAX(A.DESCRIPTION) AS DESCRIPTION , MAX(A.UNIT_MEASURE) AS UNIT_MEASURE , MAX(A.MAKER_NAME) AS MAKER_NAME , MAX(NVL(A.ATOB_UNIT_PRICE,0)) AS ATOB_UNIT_PRICE , '' AS GR_FLAG , MAX(TRIM(A.ATOB_REMARK)) AS ATOB_REMARK , MAX(DECODE((SELECT COUNT(*) FROM KEPQTDT QT WHERE QT.BUYER=A.BUYER AND QT.QUOTATION_NO=A.QUOTATION_NO AND QT.QUOTATION_SEQ=A.QUOTATION_SEQ AND QT.REVISION=A.REVISION AND QT.BID_SUCCESS_FLAG='Y' AND A.ATOB_UNIT_PRICE <> 0),0,'', DECODE(NVL(A.AGENT_OPEN_FLAG,'N'),'N', (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = 'KRKORE0001'), (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = (SELECT AGENT FROM KEPQTDT QTDT WHERE QTDT.BUYER=B.BUYER AND QTDT.QUOTATION_NO=B.QUOTATION_NO AND QTDT.QUOTATION_SEQ=B.QUOTATION_SEQ AND QTDT.REVISION=B.REVISION AND QTDT.BID_SUCCESS_FLAG='Y' AND QTDT.STATUS <> 'O' AND QTDT.STATUS <> 'D'))))) AS AGENT_NAME , MAX(A.BTOA_USER_ID) AS BTOA_USER_ID , MAX(A.BTOA_USER_NAME) AS BTOA_USER_NAME , CASE WHEN MAX(A.RECV_FLAG)='GD' THEN '견적취소' ELSE CASE WHEN MAX(A.RECV_FLAG)='CM' AND MAX((SELECT MAX(PRODUCT_CLOSE_FLAG) FROM ICOMBYIT WHERE BUYER=(SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=A.BUYER AND STATUS <> 'D') AND BUYER_ITEM_NO=A.REG_ITEM_NO AND STATUS <> 'D')) = 'G' THEN '코드부여중' ELSE CASE WHEN MAX(A.RECV_FLAG)='NG' THEN '의뢰결재중' ELSE CASE WHEN MAX(A.RECV_FLAG)='NR' THEN '의뢰반려' ELSE CASE WHEN MAX(A.RECV_FLAG)='CC' THEN '장바구니' ELSE CASE WHEN MAX(A.RECV_FLAG)='PC' THEN '발주' ELSE CASE WHEN MAX(A.RECV_FLAG)='CM' THEN '합의완료' ELSE CASE WHEN MAX(A.RECV_FLAG)='PM' THEN '견적진행중' ELSE CASE WHEN MAX(A.RECV_FLAG) = 'GS' THEN '결재진행중' ELSE CASE WHEN MAX(A.RECV_FLAG) = 'GR' THEN '결재반려' ELSE CASE WHEN MAX(A.RECV_FLAG) = 'NW' THEN '견적의뢰' ELSE CASE WHEN MAX(A.RECV_FLAG) = 'CR' THEN '견적의뢰' ELSE CASE WHEN MAX(A.RECV_FLAG) = 'RJ' THEN '견적의뢰' ELSE CASE WHEN MAX(A.KEP_USER_ID) IS NULL THEN '견적의뢰' ELSE CASE WHEN MAX(A.BTOA_NEGO_PRICE)<>0 AND MAX(A.ATOB_UNIT_PRICE)=0 AND MAX(A.ATOB_SEND_FLAG)='Y' THEN 'Nego견적의뢰' ELSE CASE WHEN MAX(A.ATOB_UNIT_PRICE)=0 AND MAX(A.BTOA_NEGO_PRICE)=0 AND MAX(A.ATOB_SEND_FLAG)='N' THEN '견적진행중' ELSE CASE WHEN MAX(A.ATOB_UNIT_PRICE)=0 AND MAX(A.BTOA_NEGO_PRICE)<>0 AND MAX(A.ATOB_SEND_FLAG)='N' THEN 'Nego진행중' ELSE CASE WHEN MAX(A.ATOB_UNIT_PRICE)<>0 AND MAX(A.BTOA_NEGO_PRICE)=0 AND MAX(A.ATOB_SEND_FLAG)='Y' AND MAX(B.BID_SUCCESS_FLAG)='Y' THEN '단가합의대상' ELSE CASE WHEN MAX(A.BTOA_NEGO_PRICE)<>0 AND MAX(A.ATOB_UNIT_PRICE)<>0 AND MAX(A.ATOB_SEND_FLAG)='Y' AND MAX(B.BID_SUCCESS_FLAG)='Y' THEN 'Nego합의대상' END END END END END END END END END END END END END END END END END END END AS SOURCING_STATUS , MAX(A.RECV_FLAG) AS RECV_FLAG , MAX(A.BUYER_ITEM_NO) AS BUYER_ITEM_NO , MAX(A.BTOA_END_DATE) AS BTOA_END_DATE , MAX(SUBSTR(NVL(A.BTOA_END_TIME,'00'),0,2))||':'||MAX(SUBSTR(NVL(A.BTOA_END_TIME,'00'),3,2)) AS BTOA_END_TIME , MAX(A.SPECIFICATION) AS SPECIFICATION , MAX(NVL(A.ITEM_QTY,0)) AS ITEM_QTY , MAX((SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE='M001' AND CODE=A.ORIGIN_CODE)) AS ORIGIN_NAME , MAX(NVL(A.BTOA_NEGO_PRICE,0)) AS BTOA_NEGO_PRICE , '' AS PO_FLAG , MAX(A.KEP_USER_ID) AS KEP_USER_ID , MAX((SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE=A.BUYER AND TYPE='C001' AND CODE=A.BTOA_USER_DEPT)) AS BTOA_USER_DEPT , MAX(B.BID_SUCCESS_FLAG) AS BID_SUCCESS_FLAG , MAX((SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID=A.KEP_USER_ID)) AS KEP_USER_NAME , MAX(DECODE((SELECT COUNT(*) FROM KEPQTDT QT WHERE QT.BUYER=A.BUYER AND QT.QUOTATION_NO=A.QUOTATION_NO AND QT.QUOTATION_SEQ=A.QUOTATION_SEQ AND QT.REVISION=A.REVISION AND QT.BID_SUCCESS_FLAG='Y' AND A.ATOB_UNIT_PRICE <> 0),0,'', DECODE(NVL(A.AGENT_OPEN_FLAG,'N'),'N','KRKORE0001', (SELECT AGENT FROM KEPQTDT QTDT WHERE QTDT.BUYER=B.BUYER AND QTDT.QUOTATION_NO=B.QUOTATION_NO AND QTDT.QUOTATION_SEQ=B.QUOTATION_SEQ AND QTDT.REVISION=B.REVISION AND QTDT.BID_SUCCESS_FLAG='Y' AND QTDT.STATUS <> 'O' AND QTDT.STATUS <> 'D')))) AS AGENT , MAX(A.REG_ITEM_NO) AS REG_ITEM_NO , MAX(A.CONTRACT_NO) AS CONTRACT_NO , MAX(A.CONTRACT_SEQ) AS CONTRACT_SEQ , MAX((SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=A.BUYER AND STATUS IN ('C','R'))) AS BYCA_COMORG_CODE , MAX(A.AGENT_OPEN_FLAG) AS AGENT_OPEN_FLAG , MAX(A.BTOA_REMARK) AS BTOA_REMARK , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER) AS BUYER_NAME , MAX((SELECT H.CATEG_PATH FROM ICOMBYCA H WHERE H.COM_CODE = A.BUYER AND H.STD_CATEG_ID IN (SELECT CATEGORY_NO FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO))) AS BUYER_CATEG_PATH , MAX(DECODE(NVL((SELECT INCOME_PRICE_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = A.BUYER),'N'),'N',0, ((SELECT MAX(STOA_LIST_PRICE) FROM KEPQTDT QTDT WHERE QTDT.BUYER=B.BUYER AND QTDT.QUOTATION_NO=B.QUOTATION_NO AND QTDT.QUOTATION_SEQ=B.QUOTATION_SEQ AND QTDT.REVISION=B.REVISION AND QTDT.BID_SUCCESS_FLAG='Y' AND QTDT.STATUS <> 'O' AND QTDT.STATUS <> 'D')))) AS STOA_LIST_PRICE , MAX(A.IMAGE_KEY) AS IMAGE_KEY , MAX((SELECT MAX(QUOTATION_SEQ) FROM KEPQTDT QTDT WHERE QTDT.BUYER = B.BUYER AND QTDT.QUOTATION_NO = B.QUOTATION_NO AND QTDT.REVISION = B.REVISION AND QTDT.BID_SUCCESS_FLAG = 'Y' AND QTDT.STATUS NOT IN ('D', 'O') )) AS BID_SUCCESS_QUOTATION_SEQ , MAX(B.LEAD_TIME) AS LEAD_TIME FROM KEPRQDT A, KEPQTDT B WHERE 1=1
AND A.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'BGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.TEXT1 = #{st_group_info} AND COD3.FLAG = 'Y')
AND A.BUYER = #{st_buyer}
AND A.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y')
AND A.BUYER = #{st_buyer}
AND A.SO_CA_FLAG='SO' AND A.RECV_FLAG ^='TS' AND A.BUYER=B.BUYER(+) AND A.QUOTATION_NO=B.QUOTATION_NO(+) AND A.QUOTATION_SEQ=B.QUOTATION_SEQ(+) AND A.REVISION=B.REVISION(+) AND A.STATUS IN ('C','R') AND 'D' <> B.STATUS(+)
AND A.BTOA_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BTOA_USER_ID = #{st_user_id}
AND A.QUOTATION_NO LIKE '%'||#{st_quotation_no}||'%'
AND A.BTOA_USER_DEPT = #{st_btoa_user_dept_code}
AND A.BUYER_ITEM_NO = #{st_search_code}
AND A.DESCRIPTION LIKE '%'||#{st_search_code}||'%'
AND A.SPECIFICATION LIKE '%'||#{st_search_code}||'%'
AND A.BTOA_USER_NAME LIKE '%'||#{st_btoa_user_name}||'%'
AND CASE WHEN A.RECV_FLAG='GD' THEN '견적취소' ELSE CASE WHEN A.RECV_FLAG='CM' AND (SELECT MAX(PRODUCT_CLOSE_FLAG) FROM ICOMBYIT WHERE BUYER=(SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=A.BUYER AND STATUS <> 'D') AND BUYER_ITEM_NO=A.REG_ITEM_NO AND STATUS <> 'D') = 'G' THEN '코드부여중' ELSE CASE WHEN A.RECV_FLAG='CC' THEN '합의완료+장바구니' ELSE CASE WHEN A.RECV_FLAG='PC' THEN '발주' ELSE CASE WHEN A.RECV_FLAG='CM' THEN '합의완료' ELSE CASE WHEN A.RECV_FLAG='PM' THEN '견적진행중' ELSE CASE WHEN A.RECV_FLAG = 'GS' THEN '결재진행중' ELSE CASE WHEN A.RECV_FLAG = 'NG' THEN '의뢰결재중' ELSE CASE WHEN A.RECV_FLAG = 'NR' THEN '의뢰반려' ELSE CASE WHEN A.RECV_FLAG = 'GR' THEN '결재반려' ELSE CASE WHEN A.RECV_FLAG = 'NW' THEN '견적의뢰' ELSE CASE WHEN A.RECV_FLAG = 'CR' THEN '견적의뢰' ELSE CASE WHEN A.RECV_FLAG = 'RJ' THEN '견적의뢰' ELSE CASE WHEN A.KEP_USER_ID IS NULL THEN '견적의뢰' ELSE CASE WHEN A.BTOA_NEGO_PRICE<>0 AND A.ATOB_UNIT_PRICE=0 AND A.ATOB_SEND_FLAG='Y' THEN 'Nego견적의뢰' ELSE CASE WHEN A.ATOB_UNIT_PRICE=0 AND A.BTOA_NEGO_PRICE=0 AND A.ATOB_SEND_FLAG='N' THEN '견적진행중' ELSE CASE WHEN A.ATOB_UNIT_PRICE=0 AND A.BTOA_NEGO_PRICE<>0 AND A.ATOB_SEND_FLAG='N' THEN 'Nego진행중' ELSE CASE WHEN A.ATOB_UNIT_PRICE<>0 AND A.BTOA_NEGO_PRICE=0 AND A.ATOB_SEND_FLAG='Y' AND B.BID_SUCCESS_FLAG='Y' THEN '단가합의대상' ELSE CASE WHEN A.BTOA_NEGO_PRICE<>0 AND A.ATOB_UNIT_PRICE<>0 AND A.ATOB_SEND_FLAG='Y' AND B.BID_SUCCESS_FLAG='Y' THEN 'Nego합의대상' END END END END END END END END END END END END END END END END END END END LIKE '%'||#{st_sourcing_status}||'%'
AND A.BTOA_USER_ID = #{st_user_id}
AND A.RECV_FLAG ^='GD'
GROUP BY A.BUYER, A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION )X ORDER BY X.BUYER, X.QUOTATION_NO, X.QUOTATION_SEQ, X.REVISION ) Y, BNTNEGOHISTORY Z WHERE 1=1 AND Y.BUYER = Z.BUYER(+) AND Y.QUOTATION_NO = Z.QUOTATION_NO(+) AND Y.QUOTATION_SEQ = Z.QUOTATION_SEQ(+) AND Y.REVISION = Z.REVISION(+)

